INSERT INTO blog_posts(slug, title, description, body_html, status, author, og_image, published_at, updated_at)
VALUES ('half-lives', 'The Half-Lives — American Names Now Lose Half Their Births in Eleven Years', '661 names peaked above 2,000 births in a single year. Measured over the same thirty-year window, the median one loses half its annual births in twelve…', '<p>In 1992, 16177 American girls were named <a href="/name/Chelsea/">Chelsea</a>. Two years later the count was 7718.</p>
<p>That is the number worth having about a name. Not the year it arrived. The year it stopped being plausible.</p>
<p>We took every name that peaked above 2,000 births in a single year, gave each one the same 30-year look, and asked a single question: when does the annual count fall below half?</p>
<p>661 names had a full window. 604 of them halved. 57 never did.</p>
<p>The median half-life across the whole cohort: 12 years.</p>
